生成一个 sim block。
契约:
{ "type":"sim", "engine":"dynamics1d", "params":[{"name":"标识符","label":"标签","min":0,"max":2,"step":0.05,"default":0.9}], "model":{ "stateVar":"c","init":0.05,"steps":40,"update":"受限表达式：仅 params名/consts键/stateVar/噪声 xi/数学函数(sin cos tan exp log sqrt abs pow min max floor round PI E)。**不要**用 steps/init/target 等 model 字段(它们是配置不是表达式变量)。例 c + alpha*(T-c) + sigma*xi","consts":{"T":1} }, "regimes":[{"when":"受限布尔表达式如 alpha<1","label":"标签","desc":"说明","tone":"line|accent|ink(可选)"}], "chart":{"xLabel":"t","yLabel":"c(t)","targetLine":{"value":1,"label":"目标"}} }
  或 searchCompare(黑箱优化三策略): { "type":"sim","engine":"searchCompare","params":[{"name":"n","label":"预算 n =","min":5,"max":30,"step":1,"default":12,"decimals":0}],"model":{"objective":"受限表达式,变量只有 x,如 sin(x)+sin(10*x/3)","domain":[2.7,7.5],"yDomain":[-2.4,2.2],"strategies":["grid","random","bayes"],"budgetParam":"n"},"labels":{"grid":"网格","random":"随机","bayes":"贝叶斯"} }
  或 widget（把可动画演示的过程放进 sandbox iframe，适合排序/查找/图遍历/几何作图/运动——别硬塞进 dynamics1d）: { "type":"sim","engine":"widget","caption":"一句操作说明(可选)","html":"自包含片段：<style>…</style> + 控件(button/input range) + <canvas id=cv></canvas> + <script> 用 requestAnimationFrame 动画</script>" }
  widget 硬规则：零依赖纯 vanilla(canvas/SVG+原生 JS，禁 CDN/库)；颜色读主题 token——getComputedStyle(document.documentElement).getPropertyValue('--ink'|'--accent'|'--line'|'--bg')，禁写死色值；控件写片段内；禁 <!doctype>/<html>/<h1>、禁提示语胶囊(如 提示：)、禁 @media(prefers-color-scheme)。
  选引擎（防误用）：**真正的一维递推**——状态 x(t+1) 由 x(t) 演化，如收敛/发散/增长衰减/RSI/梯度下降——才用 dynamics1d；**别拿 dynamics1d 合成信号/傅里叶级数/多变量运动/二阶振子**（那不是一维一阶递推，写出来是貌似有数学其实错的伪仿真）：**尤其简谐振动/阻尼振子/单摆等二阶系统需位置 x 与速度 v 两个状态变量，而 dynamics1d 只有一个 stateVar——把速度塞进 consts 会被当字符串算出 NaN、图表全空白；这类改用 custom（computeJs 里自维护 x,v）或 widget（canvas 动画）**。这类可动画的信号/几何/运动/算法过程一律用 widget（canvas 动画）；一维黑箱优化→searchCompare；都不贴切就别放 sim（改用 flow/compare 讲清即可）。

本讲义课题: 「简谐振动与阻尼」——本 block 所有内容必须紧扣此课题，标题/副题/示例严禁写成其它主题。所在页: 转动阻尼旋钮，看三种状态如何演化。本 block 教学意图: 可调阻尼比 ζ 的位移-时间曲线：ζ 从 0 到 2，实时显示欠阻尼/临界/过阻尼三种形态的位移演化，含 e^(-βt) 包络线。
只输出该 block 的 JSON。

response:
{
  "type": "sim",
  "engine": "widget",
  "caption": "拖动滑块调节阻尼比 ζ，观察位移 x(t) 随时间的演化及指数包络线",
  "html": "<style>
  .shm-wrap { display: flex; flex-direction: column; height: 100%; font-family: inherit; }
  .shm-controls { display: flex; align-items: center; gap: 12px; padding: 8px 0; flex-shrink: 0; }
  .shm-controls label { font-size: 0.9em; white-space: nowrap; }
  .shm-controls input[type=range] { flex: 1; cursor: pointer; }
  .shm-state { font-weight: bold; min-width: 80px; text-align: right; }
  canvas { width: 100%; flex: 1; min-height: 200px; display: block; }
</style>
<div class="shm-wrap">
  <div class="shm-controls">
    <label>阻尼比 ζ = <span id="zeta-val">0.10</span></label>
    <input type="range" id="zeta-slider" min="0" max="2" step="0.01" value="0.1">
    <span class="shm-state" id="state-label">欠阻尼</span>
  </div>
  <canvas id="cv"></canvas>
</div>
<script>
  const canvas = document.getElementById('cv');
  const ctx = canvas.getContext('2d');
  const slider = document.getElementById('zeta-slider');
  const zetaVal = document.getElementById('zeta-val');
  const stateLabel = document.getElementById('state-label');

  let zeta = 0.1;
  const w0 = 2.0;
  const dt = 0.02;
  const maxT = 12;

  let x = 1.0, v = 0.0, t = 0;
  let points = [];
  let animId = null;

  function getThemeColor(varName) {
    return getComputedStyle(document.documentElement).getPropertyValue(varName).trim();
  }

  function resizeCanvas() {
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = rect.width * dpr;
    canvas.height = rect.height * dpr;
    ctx.scale(dpr, dpr);
    drawFrame();
  }

  function resetSim() {
    x = 1.0; v = 0.0; t = 0;
    points = [];
    if (animId) cancelAnimationFrame(animId);
    animate();
  }

  slider.addEventListener('input', (e) => {
    zeta = parseFloat(e.target.value);
    zetaVal.textContent = zeta.toFixed(2);
    if (zeta === 0) stateLabel.textContent = '无阻尼';
    else if (zeta < 1) stateLabel.textContent = '欠阻尼';
    else if (zeta === 1) stateLabel.textContent = '临界阻尼';
    else stateLabel.textContent = '过阻尼';
    resetSim();
  });

  function stepPhysics() {
    const a = -2 * zeta * w0 * v - w0 * w0 * x;
    v += a * dt;
    x += v * dt;
    t += dt;
    points.push({ t, x });
  }

  function drawFrame() {
    const W = canvas.getBoundingClientRect().width;
    const H = canvas.getBoundingClientRect().height;
    const bg = getThemeColor('--bg');
    const ink = getThemeColor('--ink');
    const accent = getThemeColor('--accent');
    const line = getThemeColor('--line');

    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);

    const pad = 30;
    const gW = W - pad * 2;
    const gH = H - pad * 2;
    const scaleX = gW / maxT;
    const scaleY = gH / 2.5;

    ctx.save();
    ctx.translate(pad, H / 2);

    // Grid
    ctx.strokeStyle = line;
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    ctx.moveTo(0, -gH); ctx.lineTo(0, gH);
    ctx.moveTo(-pad, 0); ctx.lineTo(gW, 0);
    ctx.stroke();

    // Envelope
    ctx.strokeStyle = accent;
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    for (let i = 0; i <= gW; i++) {
      const ct = i / scaleX;
      const env = Math.exp(-zeta * w0 * ct);
      const py1 = -env * scaleY;
      const py2 = env * scaleY;
      if (i === 0) { ctx.moveTo(i, py1); } else { ctx.lineTo(i, py1); }
    }
    ctx.stroke();
    ctx.beginPath();
    for (let i = 0; i <= gW; i++) {
      const ct = i / scaleX;
      const env = Math.exp(-zeta * w0 * ct);
      const py2 = env * scaleY;
      if (i === 0) { ctx.moveTo(i, py2); } else { ctx.lineTo(i, py2); }
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // Curve
    ctx.strokeStyle = ink;
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < points.length; i++) {
      const p = points[i];
      const px = p.t * scaleX;
      const py = -p.x * scaleY;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.stroke();

    ctx.restore();
  }

  function animate() {
    if (t < maxT) {
      for(let i=0; i<2; i++) stepPhysics();
      drawFrame();
      animId = requestAnimationFrame(animate);
    }
  }

  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();
  resetSim();
</script>"
}
